statement:
Two tables record purchases:

- `Transactions(transaction_id, customer_id, product_id, transaction_date, amount)`: one row per purchase; `transaction_id` is unique, every `product_id` exists in `Products`, and `amount` is the positive sum paid.
- `Products(product_id, category, price)`: `product_id` is unique; several products can share a `category`.

For every customer who has at least one transaction, report one row with:

- `customer_id`;
- `total_amount`: the sum of the customer's `amount`s;
- `transaction_count`: how many transactions the customer made;
- `unique_categories`: how many different categories the customer bought from;
- `avg_transaction_amount`: the customer's average `amount`, rounded to 2 decimals;
- `top_category`: the category with the most of the customer's transactions; when several categories tie on that count, the one holding the customer's most recent `transaction_date` wins (the data guarantees this settles every tie);
- `loyalty_score`: `transaction_count * 10 + total_amount / 100`, rounded to 2 decimals.

Order the rows by `loyalty_score` descending, then by `customer_id` ascending.

validator:
function validate(input) {
  const [{ Transactions = [], Products = [] }] = input;
  const category = new Map();
  for (const [id, name, price] of Products) {
    if (id === null || name === null || price === null) return 'No value in Products may be null.';
    if (category.has(id)) return `product_id ${id} appears twice in Products.`;
    category.set(id, String(name).toLowerCase());
  }
  const ids = new Set(), stats = new Map();
  for (const [id, customer, product, day, amount] of Transactions) {
    if ([id, customer, product, day, amount].includes(null)) return 'No value in Transactions may be null.';
    if (ids.has(id)) return `transaction_id ${id} appears twice in Transactions.`;
    ids.add(id);
    if (!category.has(product)) return `product_id ${product} is not in Products.`;
    if (!(amount > 0)) return `amount ${amount} must be positive.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) return `transaction_date ${day} must look like 2023-01-31.`;
    if (!stats.has(customer)) stats.set(customer, new Map());
    const byCategory = stats.get(customer), key = category.get(product), entry = byCategory.get(key) ?? { count: 0, last: '' };
    entry.count++; if (day > entry.last) entry.last = day;
    byCategory.set(key, entry);
  }
  for (const [customer, byCategory] of stats) {
    const entries = [...byCategory.values()], most = Math.max(...entries.map(e => e.count));
    const tied = entries.filter(e => e.count === most), latest = tied.reduce((a, e) => e.last > a ? e.last : a, '');
    if (tied.filter(e => e.last === latest).length > 1) return `Customer ${customer} has a top-category tie that the latest date does not settle.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const pad = n => String(n).padStart(2, '0');
  const categories = small ? ['A', 'B', 'C'] : ['Books', 'Toys', 'Garden', 'Music', 'Games', 'Tools', 'Food', 'Sports'];
  const Products = [];
  const productCount = small ? Math.floor(rand() * 5) : 60;
  for (let i = 0; i < productCount; i++) Products.push([small ? i + 1 : 10 + i, pick(categories), small ? pick([100, 150, 200, 75, 40]) : 1 + Math.floor(rand() * 500)]);
  const dates = small ? ['2023-01-01', '2023-01-15', '2023-01-22', '2023-02-10', '2023-03-05', '2023-03-06', '2023-04-01']
    : Array.from({ length: 730 }, (_, i) => { const d = new Date(Date.UTC(2022, 0, 1 + i)); return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`; });
  const customers = small ? [101, 102, 103] : Array.from({ length: 400 }, (_, i) => 1000 + i);
  // At most 7 purchases per customer, each on its own date: the latest date always settles a top-category tie,
  // and whole amounts over at most 7 purchases never put an average exactly halfway between two cents.
  const used = new Map(), Transactions = [];
  const count = Products.length ? (small ? Math.floor(rand() * 9) : 2000) : 0;
  for (let i = 0; i < count; i++) {
    let customer = pick(customers);
    for (let tries = 0; (used.get(customer)?.size ?? 0) >= 7 && tries < 50; tries++) customer = pick(customers);
    if (!used.has(customer)) used.set(customer, new Set());
    const taken = used.get(customer);
    if (taken.size >= 7) continue;
    let day = pick(dates);
    while (taken.has(day)) day = pick(dates);
    taken.add(day);
    const [product, , price] = pick(Products);
    const amount = small ? (rand() < 0.6 ? price : pick([50, 100, 120, 250])) : price * (1 + Math.floor(rand() * 3));
    Transactions.push([Transactions.length + 1, customer, product, day, amount]);
  }
  return [{ Transactions, Products }];
}
